API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway container

Container_Boundary(api_gateway, "API Gateway") {
    Component(AWS WAF Filter, "AWS WAF Filter", "AWS WAF", "Inspects incoming HTTPS traffic for common web attacks and enforces rate limiting for PCI-DSS compliance.")
    Component(HTTP API Router, "HTTP API Router", "AWS API Gateway HTTP API", "Routes incoming payment authorization requests and analyst review requests to the appropriate internal ECS Fargate containers.")
    Component(Auth Validator, "Auth Validator", "AWS Cognito and JWT", "Validates JSON Web Tokens (JWT) for analyst review requests coming from the case management interface.")
}

Rel(AWS WAF Filter, HTTP API Router, "Passes filtered and rate-limited requests")
Rel(HTTP API Router, Auth Validator, "Delegates token validation for analyst requests")

@enduml

Case Management Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(case_management_container, "Case Management Container") {
    Component(ReviewInterfaceController, "Review Interface Controller", "Node.js / React", "Provides the secure review interface and API backend for fraud analysts and managers to investigate suspicious transactions.")
    Component(AuditLogger, "Audit Logger", "AWS SDK / Python", "Generates and sends immutable audit trails and tamper-evident decision logs to storage.")
    Component(QueueManager, "Queue Manager", "Node.js", "Manages SLA-driven case queues and state synchronization.")
}

Rel(ReviewInterfaceController, QueueManager, "Updates and retrieves case queue data", "")
Rel(ReviewInterfaceController, AuditLogger, "Dispatches review decisions for immutable logging", "")

@enduml

Redis Cache.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(redis_cache, "Redis Cache") {
    Component(Redis_Master_Node, "Redis Master Node", "Amazon ElastiCache Redis OSS (cache.m6g.large)", "Handles write operations and primary caching for active fallback rulesets with TLS in transit.")
    Component(Redis_Replica_Node, "Redis Replica Node", "Amazon ElastiCache Redis OSS (cache.m6g.large)", "Provides multi-AZ read redundancy to ensure high availability and sub-50ms latency for scoring queries.")
}

Rel(Redis_Master_Node, Redis_Replica_Node, "Replicates fallback ruleset data asynchronously across availability zones")

@enduml

S3 Glacier Object Lock Storage.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the S3 Glacier Object Lock Storage container

Container_Boundary(s3_glacier_object_lock_storage, "S3 Glacier Object Lock Storage") {
    Component(Object_Lock_Manager, "Object Lock Manager", "AWS S3 Glacier Flexible Archive with Object Lock and AWS KMS", "Manages WORM storage, cryptographic signing, and 7-year tamper-evident retention for audit logs.")
    Component(Firehose_Ingestion_Handler, "Firehose Ingestion Handler", "Amazon Kinesis Firehose", "Batches high-frequency logs from the Scoring Engine Container before writing to storage to reduce API costs.")
}

Rel(Firehose_Ingestion_Handler, Object_Lock_Manager, "Writes cryptographically signed audit logs", "TLS 1.3, AWS KMS")

@enduml
